def sum_of_prime_divisors(n):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    sum_of_primes = 0
    for i in range(2, n):
        if n % i == 0 and is_prime(i):
            sum_of_primes += i
    return sum_of_primes

