function rgbToHsv(r, g, b) {
  r /= 255, g /= 255, b /= 255;
  var max = Math.max(r, g, b), min = Math.min(r, g, b);
  var h, s, v = max;

  var d = max - min;
  s = max == 0 ? 0 : d / max;

  if (max == min) {
    h = 0;
 :
    return [h, s, v];
  }
  if (r == max) {
    h = (g - b) / d + (g < b ? 6 : 0);
  } else if (g == max) {
    h = (b - r) / d + 2;
  } else if (b == max) {
    h = (r - g) / d + 4;
  }
  h /= 6;

  return [h, s, v];
}

