Here is the algorithm from Wikipedia:

    function mult(long)
    {
        if length(long) < 10
            return multRec(long, length(long))
        else
        {
            split long into two halves
            let la = left half
            let lb = right half
            let m = length(long)
            let n = m/2

            let p = mult(la)
            let q = mult(lb)

            let r = mult(add(la, -lb), n)

            return add(p, add(q, add(mul(4, add(p, q)), mul(mul(base(long), r)))
        }
    }

